DOC = dict(path='notes/practice-exam.pdf', title='ENN583 2026 practice exam', pages=13)
Q = [
 ('w02', 'Which output is produced by the description stage of an image feature pipeline?', ['The final camera trajectory', 'A representation of the appearance around each detected feature', 'A list of camera exposure times only', 'The three-dimensional position of every scene point'], 1, 'Description turns the neighbourhood of each detected point into a “fingerprint” vector (W2 p21). <i>Best distractor:</i> (d) is triangulation, which comes much later.'),
 ('w02', 'An indoor robot observes a floor made from repeating square tiles. What problem is most likely to occur during feature matching?', ['Several tiles may provide plausible matches for the same detected feature.', 'Perspective projection is disabled by repeating textures.', 'Descriptors from all tiles must have different dimensions.', 'Feature matching becomes unnecessary because the floor is planar.'], 0, 'Repeated patterns cause ambiguity / visual aliasing (W2 p20). (d) is tempting but false: planarity doesn’t remove the need to match.'),
 ('w02', 'Which observation most directly satisfies the FAST corner criterion presented in the lecture?', ['A long contiguous arc of circle pixels is darker than the centre by more than the threshold.', 'Several separated circle pixels have exactly the same value as the centre.', 'The whole image has a high average brightness.', 'The candidate has already been matched in another image.'], 0, 'FAST: N contiguous circle pixels all brighter or all darker than the centre by more than t (W2 p76).'),
 ('w02', 'Nearest descriptor distances are 35 and 40. The ratio-test threshold is 0.80, and acceptance requires a ratio strictly below the threshold. Result?', ['Retain the match because 35 &lt; 40.', 'Retain the match because every ratio below one is accepted.', 'Reject the match because 35/40 = 0.875 is not below 0.80.', 'Reject the match because the ratio is greater than one.'], 2, '35/40 = 0.875 ≥ 0.80 → reject (verified in the check script). (a) and (b) ignore the threshold; (d) has the ratio the wrong way round.'),
 ('w02', 'SuperGlue receives local features that have already been detected and described, then produces correspondences for geometric pose estimation. What role does SuperGlue play?', ['It captures the images and calibrates the camera before feature extraction.', 'It replaces the camera with a wheel-odometry sensor.', 'It requires every feature to be accepted as a match.', 'It uses extracted local features to produce correspondences for the geometric back end.'], 3, 'SuperGlue is the learned matching “middle-end”. (c) is wrong because the dustbin explicitly rejects unmatched points.'),
 ('w02', 'Why is LightGlue’s ability to stop processing an easy image pair earlier useful for a mobile robot?', ['It guarantees that every easy pair contains more correct matches.', 'It removes the need to detect or describe local features.', 'It makes runtime independent of the amount of computation performed.', 'It can reduce average latency and computation while using more work for difficult pairs.'], 3, 'Adaptive depth lowers average compute (Table 5: 1.86× speed-up on easy pairs). (a) “guarantees” is an absolute; (b) is false, it still needs SuperPoint/DISK.'),
 ('w03', 'In the pinhole-camera equation, what is the role of the intrinsic matrix K?', ['It determines the world-frame position of every object without a pose.', 'It maps camera-frame coordinates into image coordinates using the camera’s internal parameters.', 'It matches feature descriptors between images.', 'It stores the camera’s frame-to-frame translation history.'], 1, 'K holds the focal length (px) and principal point and maps the normalised camera frame to pixels; the pose is in [R|t].'),
 ('w03', 'Camera system 2 has a larger physical baseline than system 1. Which trade-off applies to camera system 2?', ['Higher depth error and a smaller minimum measurable depth in every case', 'No effect because baseline is absent from the depth equation', 'Lower depth error, but a larger minimum measurable depth and harder matching for close objects', 'Elimination of all occlusions between the views'], 2, 'δZ ∝ Z²/(fb) falls with b, while Zmin = fb/dmax rises (W3 p64). (a) is exactly reversed.'),
 ('w03', 'A matcher searches a square area in the second stereo image. What change is justified after the calibrated images have been rectified?', ['Restrict the search to the corresponding image column.', 'Accept only a feature at the identical horizontal coordinate.', 'Restrict the search to the corresponding image row.', 'Remove all geometric restrictions from the search.'], 2, 'Rectification makes epipolar lines horizontal → 1-D search along the same row. (b) would force disparity 0 (a point at infinity).'),
 ('w03', 'A point has depth Z = 4 m and appears at u = 270. cu = 320 and f = 500 px. What is its X coordinate in the camera frame?', ['−0.40 m', '0.40 m', '−4.0 m', '40 m'], 0, 'X = (u − cu)Z/f = (270 − 320)·4/500 = −0.40 m (left of the optical axis). (b) drops the sign.'),
 ('w04', 'After a feature is selected in image 1, what restriction does the Fundamental matrix impose on its match in image 2?', ['The match must have the same descriptor value in every component.', 'The match must lie on the corresponding epipolar line.', 'The match must be at the principal point.', 'The match must always be on the same row, even for unrectified cameras.'], 1, 'x′ᵀFx = 0 ⇔ x′ lies on l′ = Fx. (d) holds only after rectification.'),
 ('w04', 'Why can RANSAC recover a useful geometric model even when the full match set contains outliers?', ['Every random sample is guaranteed to contain only inliers.', 'Descriptor distance and geometric error are always identical.', 'Some random minimal samples may contain only inliers and generate a model supported by many matches.', 'RANSAC changes the camera intrinsics until all matches agree.'], 2, 'That is exactly why k = log(1−p)/log(1−wⁿ) iterations are run. (a) is an absolute claim and false.'),
 ('w04', 'A RANSAC inlier threshold is changed from 2 px to 5 px while the model hypothesis and residuals remain fixed. Which statement is correct?', ['Every previous inlier becomes an outlier and some previous outliers may become inliers.', 'Every previous inlier remains an inlier, and some previous outliers may become inliers.', 'The inlier set must remain exactly unchanged.', 'The inliers will now produce a better solution than before when refining them with least squares.'], 1, 'Residual &lt; 2 implies residual &lt; 5, so the inlier set can only grow. (d) doesn’t follow: the extra points may be noise or outliers.'),
 ('w04', 'A monocular 2D–2D VO system reports translation vector (0.6, 0, 0.8). What additional information is required to report the translation in metres?', ['A different ordering of the same image correspondences', 'The rotation matrix', 'A metric scale estimate', 'The calibrated Fundamental matrix'], 2, '(0.6, 0, 0.8) is a unit direction; scale is unobservable from two views (W4 p72). R is already known.'),
 ('w05', 'Using the convention that ᴬT_B maps coordinates from frame B to frame A, which composition maps a point from frame C to frame A?', ['ᴬT_C = ᴮT_C ᴬT_B', 'ᴬT_C = (ᴬT_B)⁻¹ ᴮT_C', 'ᴬT_C = ᴬT_B + ᴮT_C', 'ᴬT_C = ᴬT_B ᴮT_C'], 3, 'Apply ᴮT_C first (C → B), then ᴬT_B (B → A); the inner indices cancel. (a) is the wrong multiplication order; (c) adds transforms.'),
 ('w04', 'RANSAC hypotheses A, B, C and D are supported by 52, 48, 61 and 55 observations. Which wins under a largest-consensus rule?', ['Hypothesis C', 'Hypothesis A', 'Hypothesis B', 'Hypothesis D'], 0, '61 is the largest inlier set.'),
 ('w05', 'A monocular VO estimate contains rotation and translation direction but no distance. Which additional measurement could make the translation metric?', ['A known scene distance or an external metric sensor measurement', 'A different permutation of the same 2D correspondences', 'The number of bits in each descriptor', 'The image filenames'], 0, 'Known distances, stereo, depth, IMU or wheel odometry fix the scale. The others are distractors that sound technical but are irrelevant.'),
 ('w05', 'What is the difference between a minimal solver and final pose refinement in a P3P/RANSAC pipeline?', ['The minimal solver creates hypotheses from three correspondences; refinement uses a larger inlier set for accuracy.', 'Refinement must discard all correspondences used by RANSAC.', 'The minimal solver estimates only image colour, while refinement estimates depth.', 'Both stages must use exactly three correspondences.'], 0, 'W5 p30–34: the minimal solver plus RANSAC is robust; refinement over the inliers is accurate.'),
 ('w05', 'A candidate pose projects a landmark to (100, 80); observed (97, 84). Residual = observed − predicted, threshold 6 px. Classification?', ['Residual (3, −4), error 7 pixels, outlier', 'Residual (−3, 4), error 25 pixels, outlier', 'Residual (197, 164), error 5 pixels, inlier', 'Residual (−3, 4), error 5 pixels, inlier'], 3, '(97−100, 84−80) = (−3, 4); √(9+16) = 5 &lt; 6 → inlier. (b) uses the squared norm; (a) has the sign flipped and the wrong norm.'),
 ('w05', 'What complementary roles do RANSAC and iterative PnP play?', ['Iterative PnP detects image corners; RANSAC calculates descriptors.', 'RANSAC provides robust hypothesis selection; iterative PnP improves the selected pose using its inliers.', 'RANSAC supplies metric camera intrinsics; iterative PnP changes the image resolution.', 'Both methods merely reorder the same matches without estimating a pose.'], 1, 'Robust selection, then accurate refinement.'),
 ('w05', 'If the probability that one correspondence is an inlier is w, an s-point sample is all-inlier with probability wˢ. What happens as s increases (0 &lt; w &lt; 1 fixed)?', ['The all-inlier probability decreases exponentially, so more RANSAC trials are required.', 'The all-inlier probability increases linearly.', 'The all-inlier probability remains equal to w.', 'The required RANSAC trials necessarily fall to one.'], 0, 'With w = 0.5, p = 0.99: s = 3 → 35 trials, s = 8 → 1177 (verified).'),
 ('w06', 'The chain predicts relative motion T_chain from keyframe 2 to 8; a direct estimate T_direct differs slightly. What should a pose graph do?', ['Force both measurements to become numerically identical before constructing the graph.', 'Discard all consecutive measurements because a non-consecutive measurement is always exact.', 'Treat both transforms as absolute camera poses in the world frame.', 'Adjust the pose variables to find a configuration that balances the weighted measurement residuals.'], 3, 'MAP = weighted nonlinear least squares over all factors. (b) uses “always exact”, an absolute.'),
 ('w06', 'Factor A and Factor B have the same residual. A has σ = 0.5, B σ = 1.0. For a squared normalised residual, which is correct?', ['Factor A contributes twice as much as Factor B.', 'Factor B contributes four times as much as Factor A.', 'Factor A contributes four times as much as Factor B.', 'Their contributions are equal.'], 2, '(r/0.5)² = 4r² vs r². (a) uses 1/σ instead of 1/σ².'),
 ('w06', 'Which action most directly reduces the risk that a local pose-graph optimiser converges to an implausible solution?', ['Set every pose and rotation matrix entry to zero.', 'Remove all measurements that agree with the initial trajectory.', 'Provide a physically plausible initial trajectory close to the expected solution.', 'Assume that robust loss functions make initialisation irrelevant.'], 2, 'Local minima: the solution depends on the initial guess (W6 p58–59).'),
 ('w06', 'Why can two posterior distributions with the same MAP state imply different decisions for a robot?', ['A MAP state contains the complete covariance of both distributions.', 'Their probability mass may have different spread or shape even though their maxima occur at the same state.', 'Equal MAP states require both posterior distributions to be identical.', 'The MAP operation changes the robot’s coordinate frame.'], 1, 'MAP discards the uncertainty (W6 p90).'),
 ('w08', 'A network must assign one of six terrain classes to every pixel. Which combination is aligned with the task?', ['One scalar logit, angular regression loss, and mean angle error', 'Four box coordinates, IoU box loss, and detection average precision', 'One global embedding, contrastive retrieval loss, and recall at 5', 'Per-pixel class logits, cross-entropy loss, and mean mask IoU'], 3, 'Semantic segmentation row of the task table (W8 p24, W11 p4).'),
 ('w13', 'A collision detector stops when its hazard score exceeds a threshold. Which threshold change reduces missed hazards at the cost of more unnecessary stops?', ['Raise the threshold.', 'Keep the threshold fixed and multiply all reported scores by zero.', 'Remove the score from the stopping decision.', 'Lower the threshold.'], 3, 'Lower threshold → more positives → higher recall, more false positives (W8 p82).'),
 ('w13', 'A model has high average accuracy, but misses a rare safety-critical object and its latency causes stale predictions. Best conclusion?', ['High average accuracy proves that rare-class recall and real-time behaviour are acceptable.', 'Latency cannot affect robot behaviour if the model’s image labels are accurate.', 'The rare failures should be removed from evaluation because they reduce the average.', 'Aggregate accuracy alone is insufficient; class-specific hazards, temporal behaviour, and latency must also be evaluated.'], 3, 'W8 p79–83, W10 p69–70.'),
 ('w09', 'Which conclusion is justified by photorealistic novel views from a 3D Gaussian-splat representation?', ['The representation models appearance well for the tested views, but physical occupancy still requires validation.', 'Every Gaussian corresponds exactly to a solid object with known metric boundaries.', 'Every transparent or reflective surface is guaranteed to be reconstructed correctly.', 'Every volume without an opaque Gaussian is guaranteed collision-free.'], 0, 'The other options all use “every” or “guaranteed”.'),
 ('w09', 'A learned monocular model outputs metric depth, but has large errors on transparent doors. Is metric output alone sufficient for collision avoidance?', ['Yes; metric units guarantee correct depth at every pixel.', 'Yes; transparent regions can be treated as free whenever the network reports the background.', 'No; metric depth cannot be back-projected with camera intrinsics.', 'No; physical units address scale, but the transparent-surface geometry and coordinate alignment still require validation.'], 3, '(c) is false: metric depth can be back-projected with K.'),
 ('w10', 'Box A has area 60 px², box B 50 px², intersection 30 px². What is their IoU?', ['0.273', '0.375', '0.50', '0.60'], 1, '30/(60+50−30) = 30/80 = 0.375 (verified). 0.273 = 30/110 forgets to subtract the intersection; 0.6 = 30/50.'),
 ('w10', 'What is the main difference between average precision and precision measured at one deployed confidence threshold?', ['AP measures only object size, while deployed precision measures class frequency.', 'AP is recall at one threshold with a different name.', 'The two measures must always be numerically identical.', 'AP summarises performance across thresholds, while the deployed precision describes one operating point.'], 3, 'W10 p67–69.'),
 ('w11', 'A segmentation model predicts background everywhere and achieves high pixel accuracy because obstacles are rare. What is the most direct training problem?', ['The unweighted objective is dominated by the common background class.', 'The model has too many obstacle pixels in its labels.', 'Semantic segmentation cannot represent obstacles.', 'High background accuracy proves obstacle recall is high.'], 0, 'Class imbalance; fix with weighting, focal or Dice loss.'),
 ('w11', 'Which expression defines IoU for a predicted mask P and ground-truth mask G?', ['|P ∩ G|/|G|', '|P ∩ G|/|P ∪ G|', '|P ∩ G|/|P|', '|P ∩ G|/|all image pixels|'], 1, '(a) is recall-like; (c) is precision-like.'),
 ('w12', 'q = (0.8, 0.6), a = (0.8, 0.6), b = (−0.8, −0.6), all unit length. Cosine similarities with q?', ['Both similarities are 1 because all descriptors are unit length', 'Both similarities are 0 because the components cancel', 'qᵀa = 1 and qᵀb = −1', 'qᵀa = −1 and qᵀb = 1'], 2, 'qᵀa = 0.64 + 0.36 = 1; b = −q gives −1.'),
 ('w12', 'For five place-recognition queries, the first correct match appears at ranks 2, 5, 1 and 6; no correct match for the fifth query. What is recall@2?', ['1/5 = 0.20', '2/5 = 0.40', '3/5 = 0.60', '4/5 = 0.80'], 1, 'Ranks ≤ 2: queries 1 (rank 2) and 3 (rank 1) → 2/5. The query with no match still counts in the denominator.'),
 ('w12', 'A place-recognition system must scale to a large database and avoid false loop closures in repeated corridors. Which design best balances these needs?', ['Geometrically compare every local feature with the entire database and accept the pair with the most raw matches.', 'Use only the top global similarity and assume repeated corridors share the same pose.', 'Use compact global descriptors for candidate search, then rerank using local spatial evidence and accept only geometrically consistent candidates.', 'Store one average corridor descriptor and accept it for every query.'], 2, 'Fast global retrieval + geometric verification (W12 p77–80). (a) doesn’t scale; (b) causes false loops from aliasing.'),
 ('w13', 'A bin contains 10 predictions with mean confidence 0.60; eight are correct. Which statement is correct?', ['Accuracy is 0.80, so the bin is overconfident by 0.20.', 'Accuracy is 0.60, so the bin is perfectly calibrated.', 'Accuracy is 0.80, so the bin is underconfident by 0.20.', 'Accuracy is 0.20, so the bin is overconfident by 0.40.'], 2, 'Accuracy &gt; confidence → under-confident. (a) has the direction backwards.'),
 ('w13', 'A system processes 50 inputs, makes 40 predictions and abstains on 10. Four predictions are wrong. Coverage and selective risk?', ['Coverage 0.80 and selective risk 0.10', 'Coverage 0.80 and selective risk 0.08', 'Coverage 0.20 and selective risk 0.10', 'Coverage 0.20 and selective risk 0.08'], 0, '40/50 = 0.80; 4/40 = 0.10. (b) divides by all inputs.'),
 ('w13', 'Why should a detector’s operating threshold not be chosen by repeatedly checking the final test set?', ['Thresholds can be selected only before any model is trained.', 'The test set would influence the selected system and no longer provide an independent final estimate.', 'A test set cannot contain confidence scores.', 'Repeated test use automatically changes the ground-truth labels.'], 1, 'Tune on validation; the test set is for one final estimate (W8 p36).'),
]
def render(mcq, notes_box):
    head = f'''<section data-panel="past" hidden aria-label="Practice exam solved"><div><p class="note mono">40 MCQs · no official answer key</p><h2>Practice exam, solved</h2>
<p class="lead">Every answer is derived from the lecture slides; every number is checked in <code>src/checks/check_all.py</code>. Try each question before opening its answer. Each solution says why the answer is right and why the most tempting wrong option fails. No question is ambiguous enough to need two readings. The only fine points are signs (Q10, Q19) and strict inequality (Q4), which are flagged where they occur.</p></div>
{notes_box(DOC, 'Question paper')}'''
    qs = ''.join(mcq(f'{t}-pe{i+1}', s, o, a, w, (f'Q{i+1}', t.upper().replace('W0', 'W')), num=f'Q{i+1}') for i, (t, s, o, a, w) in enumerate(Q))
    return head + '<div class="sub">' + qs + '</div></section>'
